import{_ as t,o,c as l,af as a}from"./chunks/framework.BSym9njW.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"zh/01-deploy/qwen36/qwen36_model.md","filePath":"zh/01-deploy/qwen36/qwen36_model.md","lastUpdated":1789635951000}'),n={name:"zh/01-deploy/qwen36/qwen36_model.md"};function d(r,e,s,i,m,c){return o(),l("div",null,[...e[0]||(e[0]=[a('<h2 id="qwen3-6-35b-a3b-模型介绍" tabindex="-1">Qwen3.6-35B-A3B 模型介绍 <a class="header-anchor" href="#qwen3-6-35b-a3b-模型介绍" aria-label="Permalink to &quot;Qwen3.6-35B-A3B 模型介绍&quot;">​</a></h2><p>Qwen3.6-35B-A3B 是通义的 MoE 文本模型（约 <strong>35B 总参 / 3B 激活</strong>）。本模块两条硬件路径：Lemonade / llama.cpp 走 <strong>GGUF + iGPU</strong>，FastFlowLM 走 <strong>NPU2 + XDNA2</strong>。不要把 GGUF 塞给 <code>flm</code>，也不要把 <code>model.q4nx</code> 塞给 llama.cpp。</p><blockquote><p>对照：同系列更早的 GPU 教程见 <a href="/hello-rocm/zh/01-deploy/qwen3/llamacpp-rocm7-deploy">Qwen3</a> · <a href="/hello-rocm/zh/01-deploy/qwen3.5/llamacpp-rocm7-deploy">Qwen3.5</a>。Lemonade 目录若写成 <code>Qwen3.5-35B-A3B-GGUF</code>，那是另一代，不要当 3.6 用。以 <code>lemonade list</code> 里带 <strong>3.6</strong> 的 id 为准。</p></blockquote><hr><h3 id="路径对照" tabindex="-1">路径对照 <a class="header-anchor" href="#路径对照" aria-label="Permalink to &quot;路径对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">路径</th><th style="text-align:left;">格式</th><th style="text-align:left;">典型体积</th><th style="text-align:left;">运行时</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>GPU / Lemonade</strong></td><td style="text-align:left;">GGUF（目录 <code>Qwen3.6-35B-A3B-GGUF</code>，多为 UD-Q4）</td><td style="text-align:left;">约 20–23 GiB</td><td style="text-align:left;">Lemonade <code>llamacpp:vulkan</code>（或 <code>rocm</code>）@ <strong>13305</strong></td></tr><tr><td style="text-align:left;"><strong>NPU / FastFlowLM</strong></td><td style="text-align:left;">NPU2</td><td style="text-align:left;">常驻约 <strong>29 GiB</strong></td><td style="text-align:left;"><code>flm serve qwen3.6-moe:35b-a3b</code> @ <strong>8219</strong></td></tr></tbody></table><p>比 Gemma 4 E4B（约 9 GiB）更吃统一内存。先停其它大模型再开。NPU 短问并发 1/2/4/8 已在验证机通过，单路长生成大约 <strong>14 tok/s</strong>。</p><hr><h3 id="部署入口" tabindex="-1">部署入口 <a class="header-anchor" href="#部署入口" aria-label="Permalink to &quot;部署入口&quot;">​</a></h3><ul><li><a href="./fastflowlm-npu-deploy">FastFlowLM NPU</a></li><li><a href="./lemonade-gpu-deploy">Lemonade GPU</a></li><li><a href="./lemonade-npu-deploy">Lemonade NPU</a></li></ul><p>环境：<a href="/hello-rocm/zh/00-environment/fastflowlm">FastFlowLM</a> · <a href="/hello-rocm/zh/00-environment/lemonade">Lemonade</a> · <a href="/hello-rocm/zh/00-environment/xdna2-npu">XDNA2</a></p>',11)])])}const f=t(n,[["render",d]]);export{p as __pageData,f as default};
